/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-09: new module - the reload of the flows after a change in storage
 *   (watchFlows of the storage plugin, preReload hook, deploy.reload settings)
 *   Z-09: review fixes - a strict read of storage (getFlows({strict: true})); a
 *   superseded cycle checks the revision in storage again (no lost reload);
 *   after the retries were exhausted storage is read every retry.max; one retry
 *   timer, timers unref, waits ended by stop()
 *   Z-16: health.unreadyGrace - after /ready turned 503 the flows are not
 *   reloaded before the grace has passed (in parallel with the preReload hook)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * The reload of the flows after a change in storage (Z-09, contract E-01
 * part B - design/engine-extensions/ZASADY.md §2.3).
 *
 * Enabled with `deploy.reload.watch: true` and a storage plugin that provides
 * the optional `watchFlows(callback)`. Without either the module does nothing
 * (the behaviour of the base version).
 *
 * ```js
 * deploy: {
 *     reload: {
 *         watch: false,              // observe storage (watchFlows)
 *         type: "full",              // "full" | "diff" - restart all or only the changed flows
 *         preReloadTimeout: 1200000, // limit of the preReload hook (drain), ms
 *         concurrency: 1,            // optional: reloads at the same time in the cluster (Z-10 slots)
 *         retry: { min: 1000, max: 60000, attempts: 10 } // storage read failures
 *     }
 * }
 * ```
 *
 * One cycle:
 *  1. a notification - while a cycle runs, notifications are coalesced into
 *     one following cycle; before the end of the first start of the flows they
 *     are buffered
 *  2. storage is read (no lock); the same revision as the active one and no
 *     `credentialsChanged` - nothing to do (an own write or a duplicate)
 *  3. instance state "reloadPending" (no lock); with `concurrency` a reload
 *     slot is claimed through the coordination (`/ready` unchanged while waiting)
 *  4. "draining" (`/ready` 503): the `preReload` hook, at most `preReloadTimeout`;
 *     with `health.unreadyGrace` (and `health.enabled`) the reload also waits
 *     until that many ms have passed since `/ready` turned 503 - at the same
 *     time as the hook, so the wait is the longer of the two, and at most
 *     `preReloadTimeout`; a deployment on this instance or a stop ends it;
 *     a deployment (or POST /flows/state) on this instance in steps 3-4 supersedes
 *     the reload; one more cycle then compares the revision in storage with the
 *     active one (a failed deployment saved nothing)
 *  5. under the deploy lock: storage is read again (the newest revision) and
 *     the configuration is reloaded ("reloading") - nothing is saved, the
 *     flows of an idle instance are not started; flows changed during the drain
 *     outside of the drained ones get one more `preReload` (outside the lock,
 *     D-17), at most once (R-36)
 *  6. the slot is released; `runtime-deploy` is emitted by the reload
 *
 * The `preReload` hook - `RED.hooks.add("preReload", handler)` - may only delay
 * the reload: a rejection, an exception, `false` or the timeout are logged and
 * the reload goes on (R-20). The payload (frozen):
 *
 * @typedef PreReloadEvent
 * @type {object}
 * @property {string} rev - the revision that will be started
 * @property {string|null} activeRev - the running revision
 * @property {"full"|"diff"} type
 * @property {string[]|null} changedFlows - the ids of the flows (tabs and subflows)
 *     that are restarted; null when all flows are restarted
 * @property {boolean} credentialsChanged
 * @property {number} deadline - Date.now() + preReloadTimeout when the drain started
 * @property {AbortSignal} signal - aborted with the reason "stopping" (the runtime
 *     stops) or "superseded" (a deployment on this instance)
 * @module
 */

const health = require("../health");

const DEFAULT_TIMEOUT = 1200000;
const DEFAULT_RETRY = { min: 1000, max: 60000, attempts: 10 };
const TYPES = ["full", "diff"];
const SLOT_NAME = "reload";
const SLOT_TTL = 60000;
// D-18, R-36: a read error or an incomplete configuration (a missing, empty or
// invalid flow file) rejects the read instead of reloading an empty configuration
const STRICT_READ = Object.freeze({ strict: true });

function isPositiveNumber(value) {
    return typeof value === "number" && isFinite(value) && value > 0;
}

/**
 * Creates a reloader. The runtime uses the instance exported by this module;
 * the tests create separate instances.
 * @param {object} [deps] - the instance state, the deploy pipeline and the deploy
 *     lock (default: the modules of the runtime)
 */
function createReloader(deps) {
    deps = deps || {};
    const instanceState = deps.state || require("../state");
    const pipeline = deps.pipeline || require("./pipeline");
    const lock = deps.lock || require("./lock");

    let runtime = null;
    let log = null;
    let config = null;
    let registered = false;
    let stopped = false;
    let startupDone = false;
    let buffered = false;
    let running = false;
    let pending = false;
    let credentialsHint = false;
    // After the retries were exhausted ("failed"): the next cycle reloads even
    // when the revision is unchanged, so the instance can become ready again
    let forceNext = false;
    let readFailures = 0;
    // After the retries were exhausted: storage is read again every retry.max
    // until a read succeeds (the instance becomes ready again)
    let exhausted = false;
    let retryTimer = null;
    // Aborted by stop(): ends the waits (sleep) of the reloader
    let stopController = new AbortController();
    let unwatch = null;
    let unsubscribeState = null;
    // The running cycle: {controller, slot}
    let cycle = null;

    function readConfig(settings) {
        const deploy = (settings && settings.deploy) || {};
        const reload = (deploy.reload && typeof deploy.reload === "object") ? deploy.reload : {};
        const result = {
            watch: reload.watch === true,
            type: "full",
            preReloadTimeout: DEFAULT_TIMEOUT,
            concurrency: 0,
            // Z-16: invalid values are reported by health.init(), here 0 (off)
            unreadyGrace: health.resolveUnreadyGrace(settings).ms,
            retry: Object.assign({}, DEFAULT_RETRY)
        };
        if (reload.type !== undefined) {
            if (TYPES.indexOf(reload.type) !== -1) {
                result.type = reload.type;
            } else {
                log.warn(log._("reload.invalid-type", { value: String(reload.type) }));
            }
        }
        if (reload.preReloadTimeout !== undefined) {
            if (isPositiveNumber(reload.preReloadTimeout)) {
                result.preReloadTimeout = reload.preReloadTimeout;
            } else {
                log.warn(log._("reload.invalid-timeout", { value: String(reload.preReloadTimeout) }));
            }
        }
        if (reload.concurrency !== undefined) {
            // R-20: only a number of instances, no percentage
            if (Number.isInteger(reload.concurrency) && reload.concurrency >= 1) {
                result.concurrency = reload.concurrency;
            } else {
                log.warn(log._("reload.invalid-concurrency", { value: String(reload.concurrency) }));
            }
        }
        const retry = (reload.retry && typeof reload.retry === "object") ? reload.retry : {};
        ["min", "max"].forEach(function(key) {
            if (retry[key] !== undefined) {
                if (isPositiveNumber(retry[key])) {
                    result.retry[key] = retry[key];
                } else {
                    log.warn(log._("reload.invalid-retry", { key: key, value: String(retry[key]) }));
                }
            }
        });
        if (retry.attempts !== undefined) {
            if (Number.isInteger(retry.attempts) && retry.attempts >= 1) {
                result.retry.attempts = retry.attempts;
            } else {
                log.warn(log._("reload.invalid-retry", { key: "attempts", value: String(retry.attempts) }));
            }
        }
        if (result.retry.max < result.retry.min) {
            result.retry.max = result.retry.min;
        }
        return result;
    }

    /**
     * @param {object} _runtime - the internal runtime api
     */
    function init(_runtime) {
        runtime = _runtime;
        log = runtime.log;
        registered = false;
        stopped = false;
        startupDone = false;
        buffered = false;
        running = false;
        pending = false;
        credentialsHint = false;
        forceNext = false;
        readFailures = 0;
        exhausted = false;
        retryTimer = null;
        stopController = new AbortController();
        unwatch = null;
        cycle = null;
        config = readConfig(runtime.settings);
    }

    /**
     * Registers the observer with the storage (`watchFlows`) - after the
     * storage and the coordination started and before the flows are read.
     * Without `deploy.reload.watch` nothing happens; a storage without
     * `watchFlows` only logs a warning.
     * @return {Promise} rejected when the storage rejects the registration (R-36)
     */
    async function register() {
        if (!config || !config.watch) {
            return;
        }
        const storage = runtime.storage;
        if (!storage || typeof storage.hasWatchFlows !== "function" || !storage.hasWatchFlows()) {
            log.warn(log._("reload.watch-not-supported"));
            return;
        }
        if (config.concurrency && isLocalCoordination()) {
            log.warn(log._("reload.concurrency-local", { concurrency: config.concurrency }));
            config.concurrency = 0;
        }
        let result;
        try {
            result = await storage.watchFlows(onNotification);
        } catch (err) {
            log.error(log._("reload.watch-failed", { message: (err && err.message) || String(err) }));
            throw err;
        }
        unwatch = typeof result === "function" ? result : null;
        registered = true;
        unsubscribeState = instanceState.onChange(onStateChange);
        log.info(log._("reload.watching", { type: config.type }));
    }

    function isLocalCoordination() {
        const coordination = runtime.coordination;
        if (!coordination || typeof coordination.claimSlot !== "function") {
            return true;
        }
        try {
            return !coordination.info || coordination.info().local !== false;
        } catch (err) {
            return true;
        }
    }

    /**
     * The end of the first start of the flows (also a failed one): the
     * buffered notifications are handled now.
     */
    function startupComplete() {
        startupDone = true;
        if (buffered && registered && !stopped) {
            buffered = false;
            schedule();
        }
    }

    /**
     * Stops observing: the running cycle is aborted ("stopping") and the
     * storage observer is unregistered.
     */
    async function stop() {
        stopped = true;
        clearRetry();
        if (!stopController.signal.aborted) {
            stopController.abort("stopping");
        }
        if (cycle) {
            abortCycle("stopping");
        }
        if (unsubscribeState) {
            unsubscribeState();
            unsubscribeState = null;
        }
        const wasRegistered = registered;
        registered = false;
        if (wasRegistered && unwatch) {
            const fn = unwatch;
            unwatch = null;
            try {
                await fn();
            } catch (err) {
                log.debug("reload: unwatch failed: " + ((err && err.message) || err));
            }
        }
    }

    // The callback given to watchFlows
    function onNotification(notification) {
        try {
            if (stopped || !registered) {
                log.debug("reload: notification ignored - not watching");
                return;
            }
            if (notification && notification.credentialsChanged === true) {
                credentialsHint = true;
            }
            // A new notification resets the retry delay
            readFailures = 0;
            clearRetry();
            if (!startupDone) {
                buffered = true;
                return;
            }
            schedule();
        } catch (err) {
            log.debug("reload: notification failed: " + ((err && err.message) || err));
        }
    }

    function onStateChange(info) {
        if (!cycle) {
            return;
        }
        if (info.state === "stopping") {
            abortCycle("stopping");
        } else if (info.state === "deploying" && info.previous === "reloadPending") {
            // A deployment on this instance supersedes the pending reload (E-02 T5)
            log.info(log._("reload.superseded"));
            abortCycle("superseded");
        }
    }

    function abortCycle(reason) {
        if (cycle && !cycle.controller.signal.aborted) {
            cycle.controller.abort(reason);
        }
    }

    function schedule() {
        if (running) {
            pending = true;
            return;
        }
        running = true;
        (async function() {
            try {
                do {
                    pending = false;
                    await runCycle();
                } while (pending && !stopped);
            } catch (err) {
                log.warn(log._("reload.failed", { message: (err && err.message) || String(err) }));
            } finally {
                running = false;
            }
        })();
    }

    // A timer that does not keep the process alive
    function unrefTimer(timer) {
        if (timer && typeof timer.unref === "function") {
            timer.unref();
        }
        return timer;
    }

    // Resolves after `ms`, when `signal` is aborted or when the reloader stops
    function sleep(ms, signal) {
        const signals = [stopController.signal];
        if (signal) {
            signals.push(signal);
        }
        return new Promise(function(resolve) {
            if (signals.some(function(s) { return s.aborted })) {
                return resolve();
            }
            const timer = unrefTimer(setTimeout(done, ms));
            function done() {
                clearTimeout(timer);
                signals.forEach(function(s) { s.removeEventListener("abort", done) });
                resolve();
            }
            signals.forEach(function(s) { s.addEventListener("abort", done) });
        });
    }

    function clearRetry() {
        if (retryTimer) {
            clearTimeout(retryTimer);
            retryTimer = null;
        }
    }

    // Schedules the next cycle after `ms`; replaces a pending retry
    function scheduleRetry(ms) {
        clearRetry();
        retryTimer = unrefTimer(setTimeout(function() {
            retryTimer = null;
            schedule();
        }, ms));
    }

    function backoff(attempt) {
        return Math.min(config.retry.max, config.retry.min * Math.pow(2, Math.max(0, attempt - 1)));
    }

    function getActiveRev() {
        const active = runtime.flows.getFlows();
        return active ? active.rev : null;
    }

    // A failed read of storage: retry with an exponential delay; after
    // retry.attempts the instance state is "failed" (D-18, R-20, R-36) - the
    // running flows are not stopped - and storage is read again every
    // retry.max until a read succeeds
    function readFailed(err, credentialsChanged) {
        if (stopped) {
            return;
        }
        if (credentialsChanged) {
            credentialsHint = true;
        }
        const message = (err && err.message) || String(err);
        if (exhausted) {
            log.debug("reload: storage still unavailable: " + message);
            scheduleRetry(config.retry.max);
            return;
        }
        readFailures++;
        log.warn(log._("reload.read-failed", { message: message, attempt: readFailures, attempts: config.retry.attempts }));
        if (readFailures >= config.retry.attempts) {
            log.error(log._("reload.retries-exhausted", { attempts: readFailures }));
            readFailures = 0;
            exhausted = true;
            forceNext = true;
            instanceState.fail([{ code: "storage_error", message: message }], "storage-error");
            scheduleRetry(config.retry.max);
            return;
        }
        scheduleRetry(backoff(readFailures));
    }

    // Waits until a running operation under the deploy lock has completed
    async function waitForOperation() {
        await lock.runExclusive(async function() {});
        await sleep(config.retry.min);
    }

    async function acquireSlot(signal) {
        let failures = 0;
        while (!signal.aborted) {
            try {
                const claim = await runtime.coordination.claimSlot(SLOT_NAME, config.concurrency, SLOT_TTL);
                if (claim) {
                    return claim;
                }
                log.debug("reload: waiting for a reload slot");
                failures = 0;
                await sleep(config.retry.min, signal);
            } catch (err) {
                // R-20: no connection to the coordinator - the reload waits,
                // the old configuration keeps running
                failures++;
                log.warn(log._("reload.slot-claim-failed", { message: (err && err.message) || String(err) }));
                await sleep(backoff(failures), signal);
            }
        }
        return null;
    }

    function holdSlot(claim) {
        if (!claim || typeof claim.renew !== "function") {
            return null;
        }
        const timer = setInterval(function() {
            Promise.resolve().then(function() { return claim.renew(SLOT_TTL) }).then(function(kept) {
                if (kept === false) {
                    log.warn(log._("reload.slot-lost"));
                }
            }, function(err) {
                log.debug("reload: slot renew failed: " + ((err && err.message) || err));
            });
        }, Math.floor(SLOT_TTL / 3));
        if (timer.unref) {
            timer.unref();
        }
        return timer;
    }

    function releaseSlot(current) {
        if (!current || !current.slot) {
            return;
        }
        if (current.renewTimer) {
            clearInterval(current.renewTimer);
        }
        const claim = current.slot;
        current.slot = null;
        Promise.resolve().then(function() {
            return typeof claim.release === "function" ? claim.release() : undefined;
        }).catch(function(err) {
            log.debug("reload: slot release failed: " + ((err && err.message) || err));
        });
    }

    // The preReload hook with the limit; resolves when the reload may go on
    function drain(info) {
        const hooks = runtime.hooks;
        if (!hooks || !hooks.has("preReload")) {
            return Promise.resolve();
        }
        const remaining = info.deadline - Date.now();
        if (remaining <= 0) {
            log.warn(log._("reload.hook-timeout", { timeout: config.preReloadTimeout }));
            return Promise.resolve();
        }
        const payload = Object.freeze({
            rev: info.rev,
            activeRev: info.activeRev,
            type: config.type,
            changedFlows: info.changedFlows ? Object.freeze(info.changedFlows.slice()) : null,
            credentialsChanged: !!info.credentialsChanged,
            deadline: info.deadline,
            signal: info.signal
        });
        return new Promise(function(resolve) {
            let finished = false;
            const timer = unrefTimer(setTimeout(function() {
                if (!finished) {
                    log.warn(log._("reload.hook-timeout", { timeout: config.preReloadTimeout }));
                }
                finish();
            }, remaining));
            function finish() {
                if (!finished) {
                    finished = true;
                    clearTimeout(timer);
                    info.signal.removeEventListener("abort", finish);
                    resolve();
                }
            }
            info.signal.addEventListener("abort", finish);
            let result;
            try {
                result = hooks.trigger("preReload", payload);
            } catch (err) {
                result = Promise.reject(err);
            }
            Promise.resolve(result).then(function(value) {
                if (value === false && !finished) {
                    log.error(log._("reload.hook-failed", { message: "false" }));
                }
                finish();
            }, function(err) {
                if (!finished && !info.signal.aborted) {
                    log.error(log._("reload.hook-failed", { message: (err && err.message) || String(err) }));
                }
                finish();
            });
        });
    }

    async function runCycle() {
        if (stopped) {
            return;
        }
        const credentialsChanged = credentialsHint;
        credentialsHint = false;
        const force = forceNext;

        // Step 2: read storage (no lock) and compare the revisions
        let loaded;
        try {
            loaded = await runtime.storage.getFlows(STRICT_READ);
        } catch (err) {
            readFailed(err, credentialsChanged);
            return;
        }
        readFailures = 0;
        exhausted = false;
        const activeRev = getActiveRev();
        if (loaded.rev === activeRev && !credentialsChanged && !force) {
            log.debug("reload: revision " + loaded.rev + " is already active");
            return;
        }

        // Step 3: "reloadPending" - no lock, no token
        if (!instanceState.markReloadPending({ reason: "reload" })) {
            // Another operation runs (a deployment, POST /flows/state): try
            // again once it has completed
            if (credentialsChanged) {
                credentialsHint = true;
            }
            if (!stopped) {
                await waitForOperation();
                pending = true;
            }
            return;
        }
        const reloadType = (config.type === "diff" && !credentialsChanged) ? "diff" : "full";
        let drained = reloadType === "diff" ? runtime.flows.getChangedFlows(loaded) : null;
        const current = cycle = { controller: new AbortController(), slot: null, renewTimer: null };
        const signal = current.controller.signal;
        try {
            if (config.concurrency) {
                current.slot = await acquireSlot(signal);
                current.renewTimer = holdSlot(current.slot);
            }
            if (signal.aborted) {
                return;
            }

            // Step 4: drain - /ready 503 from now on
            instanceState.markDraining();
            const deadline = Date.now() + config.preReloadTimeout;
            // Z-16: /ready has answered 503 since the line above; the flows are not
            // stopped before the grace has passed, counted inside preReloadTimeout
            const grace = Math.min(config.unreadyGrace, config.preReloadTimeout);
            const graceWait = grace > 0 ? sleep(grace, signal) : null;
            if (graceWait) {
                log.info(log._("reload.unready-grace", { grace: grace }));
            }
            await Promise.all([
                drain({ rev: loaded.rev, activeRev: activeRev, changedFlows: drained, credentialsChanged: credentialsChanged, deadline: deadline, signal: signal }),
                graceWait
            ]);

            // Step 5: under the deploy lock - read storage again and reload
            let extraRound = false;
            while (!signal.aborted) {
                let decision = null;
                const result = await pipeline.deploy({
                    type: "reload",
                    source: "storage",
                    reread: async function() {
                        decision = await reread({ signal: signal, drained: drained, extraRound: extraRound, credentialsChanged: credentialsChanged, force: force, reloadType: reloadType });
                        return decision;
                    }
                });
                if (result && result.rev !== undefined) {
                    forceNext = false;
                    log.info(log._("reload.reloaded", { rev: result.rev, type: decision.reloadType }));
                    log.audit({ event: "flows.reload", source: "storage", rev: result.rev, type: decision.reloadType });
                    return;
                }
                if (!decision || decision.skip) {
                    // superseded, aborted or nothing to do any more
                    if (decision && decision.skip === "unchanged") {
                        log.debug("reload: storage unchanged after the drain");
                    } else if (result && result.skipped === "superseded") {
                        // Another operation (POST /flows/state) left "reloadPending"
                        current.superseded = true;
                    }
                    return;
                }
                if (decision.error) {
                    readFailed(decision.error, credentialsChanged);
                    return;
                }
                // D-17: flows changed during the drain - one more preReload for
                // them, outside the lock, within the remaining limit
                extraRound = true;
                drained = decision.extra === null ? null : drained.concat(decision.extra);
                await drain({ rev: decision.fresh.rev, activeRev: getActiveRev(), changedFlows: decision.extra, credentialsChanged: credentialsChanged, deadline: deadline, signal: signal });
            }
        } catch (err) {
            // The reload failed before the flows were changed (for example the
            // credentials could not be loaded): the state is restored by the pipeline
            readFailed(err, credentialsChanged);
        } finally {
            releaseSlot(current);
            if (cycle === current) {
                cycle = null;
            }
            if (!stopped && (current.superseded || signal.reason === "superseded")) {
                // The cycle was superseded by an operation that may not have
                // saved to storage (POST /flows/state, a failed deployment):
                // one more cycle compares the revision in storage with the
                // active one and reloads when they differ (no lost reload)
                log.debug("reload: superseded - checking the revision in storage again");
                if (credentialsChanged) {
                    credentialsHint = true;
                }
                pending = true;
            }
        }
    }

    // Step 5, called by the pipeline under the deploy lock in "reloadPending"
    async function reread(opts) {
        if (opts.signal.aborted) {
            return { skip: "aborted" };
        }
        let fresh;
        try {
            fresh = await runtime.storage.getFlows(STRICT_READ);
        } catch (err) {
            // T7b: back to the state before the cycle, the flows keep running
            instanceState.cancelPending();
            return { error: err };
        }
        if (fresh.rev === getActiveRev() && !opts.credentialsChanged && !opts.force) {
            instanceState.cancelPending();
            return { skip: "unchanged" };
        }
        if (opts.reloadType === "diff" && opts.drained !== null) {
            const now = runtime.flows.getChangedFlows(fresh);
            const extra = now === null ? null : now.filter(function(id) { return opts.drained.indexOf(id) === -1 });
            if (extra === null || extra.length > 0) {
                if (!opts.extraRound) {
                    log.warn(log._("reload.changed-during-drain", { flows: extra === null ? "*" : extra.join(", ") }));
                    return { extra: extra, fresh: fresh };
                }
                // R-36: at most one more round - reload the newest revision
                log.warn(log._("reload.changed-after-extra-drain", { flows: extra === null ? "*" : extra.join(", ") }));
            }
        }
        return { apply: fresh, reloadType: opts.reloadType, credentialsChanged: !!opts.credentialsChanged };
    }

    return {
        init: init,
        register: register,
        startupComplete: startupComplete,
        stop: stop
    };
}

module.exports = createReloader();
module.exports.createReloader = createReloader;
